      "nombreOriginal": "EL HOMBRE Y SU MUERTE",
      "tipoLabel": "Electiva / ARU",
      "area": "REFLEXIÓN UNIVERSITARIA T3: TRASCENDENCIA",
      "descripcion": "Identificar los aspectos fundamentales de las diversas concepciones, experiencias y tradiciones ante el papel de la muerte en la vida personal y comunitaria. Valorar el ser del hombre, su sentido de la vida y de la muerte, a través de una reflexión sobre la propia existencia personal. Identificar la relación entre el sentido de la vida, la muerte y la trascendencia.",
      "contenido": "Aproximaciones al problema de la muerte: los signos de muerte y el proceso de morir. Muerte biológica. La muerte clínica.\nLas actitudes fundamentales de ayer y hoy ante la muerte: la muerte domesticada, la muerte propia, las sepulturas, la muerte del otro. La muerte prohibida, el miedo a la muerte y la aceptación de la muerte.\nAproximaciones al hecho de la muerte: ecocidio, muerte colectiva y homicidio. Otras formas de matar: pena de muerte y eutanasia.\nLa muerte y los símbolos: rituales, ritos de duelo, el símbolo y la muerte en Occidente.\nLa muerte en México.\nEl sentido de la vida y de la muerte: trascendencia.",
