      "visibleInPlan": false,
      "visibleInCatalog": true,
      "caratulaPdf": "/assets/pdf/caratulas/suj/00_20502__EL_HOMBRE_Y_SU_MUERTE_caratula.pdf",
      "caratulaFile": "00_20502__EL_HOMBRE_Y_SU_MUERTE_caratula.pdf",
      "caratulaClave": "20502",
      "objetivosGenerales": [
        "Identificar los aspectos fundamentales de las diversas concepciones, experiencias y tradiciones ante el papel de la muerte en la vida personal y comunitaria.",
        "Valorar el ser del hombre, su sentido de la vida y de la muerte, a través de una reflexión sobre la propia existencia personal.",
        "Identificar la relación entre el sentido de la vida, la muerte y la trascendencia."
      ],
      "temario": [
        "Aproximaciones al problema de la muerte: los signos de muerte y el proceso de morir. Muerte biológica. La muerte clínica.",
        "Las actitudes fundamentales de ayer y hoy ante la muerte: la muerte domesticada, la muerte propia, las sepulturas, la muerte del otro. La muerte prohibida, el miedo a la muerte y la aceptación de la muerte.",
        "Aproximaciones al hecho de la muerte: ecocidio, muerte colectiva y homicidio. Otras formas de matar: pena de muerte y eutanasia.",
        "La muerte y los símbolos: rituales, ritos de duelo, el símbolo y la muerte en Occidente.",
        "La muerte en México.",
        "El sentido de la vida y de la muerte: trascendencia."
      ],
      "bibliografia": [
        "Ariés, Phillipe, El hombre ante la muerte en Occidente, Taurus, 2011, Madrid",
        "Instituto Mexicano de Tanatología A C, ¿Cómo enfrentar la muerte? Tanatología, Trillas, 2011, México",
        "Pérez Valera, Víctor Manuel, Eutanasia:¿piedad? ¿delito?, Universidad Iberoamericana, 2003, México",
        "Salas Parrila, Miguel, El sentido de la vida, Alianza, 2003, Madrid"
      ],
      "prerequisitosTexto": "20483 - PERSONA Y HUMANISMO"
