      "descripcion": "Explicar los diferentes elementos que constituyen el texto literario y la cinta cinematográfica. Identificar valores humanos a partir del análisis de textos literarios y de representaciones cinematográficas. Relacionar distintas posibilidades de entender el mundo a partir de la literatura y el cine. Sustentar las opiniones con respecto a problemáticas existenciales aprovechando la riqueza de los campos literario y cinematográfico.",
      "contenido": "Las características del análisis literario y cinematográfico.\nLa dignidad de la persona y sus valores en los campos literario y cinematográfico.\nLa interpretación y las posibilidades críticas frente a la representación artística.\nLa diferencia entre los géneros y subgéneros de la literatura y el cine y los distintos efectos que proyectan.\nLa dualidad ética entre 'bien' y 'mal' según la perspectiva desde donde se interprete.",
