      "descripcion": "Identificar los aportes culturales de Mesoamérica a México y a la cultura mundial. Describir las diferencias culturales de Mesoamérica y Aridoamérica para explicar las diferencias entre sur y norte de México. Enlistar los factores sociohistóricos que están en la base de la discriminación de los indígenas contemporáneos en México. Defender la propia visión sobre los indígenas mexicanos desde la revalorización de las raíces prehispánicas de lo mexicano. Recuperar los aportes de los pueblos indígenas y otros grupos que conforman la diversidad sociocultural de México.",
      "contenido": "México, un país pluriétnico y pluricultural.\nContribuciones de Mesoamérica y Aridoamérica a la conformación sociocultural de México.\nLa herencia indígena de México.\nParticipación y relevancia de los pueblos indígenas y otros grupos étnicos en los procesos sociales y culturales de México.\nDerechos de los pueblos indígenas y discriminación en México.",
