      "descripcion": "Resolver estructuras estáticamente determinadas e indeterminadas, sometidas a carga axial, torsión y flexión de materiales metálicos, poliméricos, cerámicos y reutilizables. Calcular los estados de esfuerzos producidos por fuerzas cortantes en vigas y conexiones simples. Predecir los estados de cargas y momentos por medio de los diagramas correspondientes. Evaluar elementos mecánicos sometidos a esfuerzos combinados a partir de las diferentes teorías de falla. Sustentar la estabilidad de elementos sometidos a flexión y compresión considerando condiciones de apoyo determinadas.",
      "contenido": "Cargas, esfuerzos normales y cortantes, deformación nominal y esfuerzo permisible en materiales metálicos, poliméricos, cerámicos y reutilizables.\nIsotropía, anisotropía, continuidad, linealidad, homogeneidad, diagramas esfuerzos deformación axial y cortante, comportamiento elástico y plástico del material, resilencia y tenacidad, ley de Hooke y relación de Poisson.\nTorsión en régimen elástico y plástico, flexión en régimen elástico lineal, fórmula de la flexión, deflexión.\nConcepto de flujo cortante y fórmula de esfuerzo cortante en vigas, compresión de columnas, pandeo elástico e inelástico.\nCombinación de esfuerzos producidos por fuerzas normal, cortante, flexionante, combinadas y método de superposición.\nTransformación de esfuerzos y deformaciones, vigas estáticamente indeterminadas, y efectos de la temperatura y el desplazamiento.\nTeoría de la falla, esfuerzo normal máximo y esfuerzo cortante máximo.",
